        t["STAGES"]["segments"] = LearnEntry{"Cuántos escalones/rampas en la vuelta (2–8). Más segmentos = más resolución en la forma.", "", ""};
        t["STAGES"]["rate"] = LearnEntry{"Velocidad de la vuelta en modo LOOP (0,02–20 Hz, +CV). Cada segmento tarda (1/rate)/segments, ajustado por TILT.", "", ""};
        t["STAGES"]["contour"] = LearnEntry{"La FORMA de los niveles objetivo: 0 una escalera ascendente (0→1), 0,5 un arco (0→1→0), 1 una escalera descendente — una mezcla continua. Es el 'dibujo' de la función.", "Un generador, no un editor de puntos de ruptura (identidad RASGO): la forma se esculpe con macros.", ""};
        t["STAGES"]["curve"] = LearnEntry{"Curva de transición de cada segmento: <0 exponencial (rápido→lento), 0 lineal, >0 logarítmica (lento→rápido). No hace nada con HOLD=1 (no hay transición).", "", ""};
        t["STAGES"]["hold"] = LearnEntry{"0 = cada segmento DESLIZA suave hasta el nivel siguiente (una rampa — envolvente/LFO); 1 = SALTA y se sostiene (un escalón — S&H/secuencia); en medio, sube en rampa parte del camino y sostiene el resto.", "Es el mando que convierte el STAGES en envolvente O en secuenciador sin cambiar de módulo.", ""};
        t["STAGES"]["tilt"] = LearnEntry{"Distorsión de las duraciones: <0 los segmentos del principio más largos (ataque lento), >0 los del final (relajo lento).", "", ""};
        t["STAGES"]["jitter"] = LearnEntry{"Paseo lento SEMBRADO en los niveles y las duraciones — la forma 'respira' sin dejar de ser reproducible (jitter=0 → sin término, idéntico byte a byte).", "", ""};
        t["STAGES"]["loop"] = LearnEntry{"Corre libre (un LFO complejo de N segmentos) ↔ un disparo (una envolvente — necesita el GATE; se congela en el último nivel hasta el próximo gate).", "", ""};
        t["STAGES"]["in:gate"] = LearnEntry{"Modo one-shot (LOOP apagado): el flanco de subida inicia una pasada. Ignorado en modo loop.", "", ""};
