        t["STAGES"]["out:eoc"] = LearnEntry{"Pulso al final de la vuelta (end-of-cycle) — encadénelo al RESET de otra instancia.", "", ""};
        t["STAGES"]["out:step"] = LearnEntry{"Pulso en cada frontera de segmento — STEP → ENVELOPE.gate encadena un AD por segmento.", "", ""};
        t["DRIFT"]["rate"] = LearnEntry{"Ritmo del paseo del campo compartido — en escala de MINUTOS, no de audio.", "", ""};
        t["DRIFT"]["depth"] = LearnEntry{"Alcance del paseo — cuánto puede alejarse el campo del reposo.", "", ""};
        t["DRIFT"]["momentum"] = LearnEntry{"Cuánto tiende la velocidad del paseo a continuar en vez de reaccionar al instante.", "vel = vel·(0,2+0,78·momentum) + impulso·(1,1−0,75·momentum) — momentum alto = trayectoria más suave, menos nerviosa.", ""};
        t["DRIFT"]["stride"] = LearnEntry{"0 = las 4 salidas (A-D) andan casi juntas; 1 = cada una por su lado.", "Cada salida lee el mismo campo con PESOS distintos — STRIDE controla cuánto divergen esos pesos.", ""};
        t["DRIFT"]["bias"] = LearnEntry{"Empuja el reposo del campo hacia un lado (no queda centrado en 0).", "", ""};
        t["DRIFT"]["anchor"] = LearnEntry{"Memoria de topología — cada 8 tics graba el estado como hito; con probabilidad ∝ anchor², vuelve al hito en vez de dar un paso nuevo.", "anchor=0 es paseo libre (nunca vuelve); un anchor alto hace que la deriva orbite paisajes ya visitados en vez de vagar para siempre.", ""};
        t["DRIFT"]["in:advance"] = LearnEntry{"Trigger — fuerza un paso (una cadencia por compás/frase en vez del RATE interno).", "", ""};
        t["DRIFT"]["in:rate_mod"] = LearnEntry{"CV que se suma a RATE.", "", ""};
