        t["DRIFT"]["out:c"] = LearnEntry{"Salida correlacionada C.", "", ""};
        t["DRIFT"]["out:d"] = LearnEntry{"Salida correlacionada D.", "", ""};
        t["DRIFT"]["out:field"] = LearnEntry{"El paseo crudo compartido, sin los pesos por salida.", "", ""};
        t["DRIFT"]["out:event"] = LearnEntry{"Pulso en cada tic del paseo.", "", ""};
        t["CHAOS"]["rate"] = LearnEntry{"Velocidad de la dinámica — de CV muy lenta (0,02 Hz) a textura de audio (400 Hz).", "", ""};
        t["CHAOS"]["drive"] = LearnEntry{"Fuerza de la no linealidad — cuanto más alta, con más fuerza se tira el sistema entre los dos pozos estables.", "", ""};
        t["CHAOS"]["damping"] = LearnEntry{"Amortiguamiento — alto se asienta en un solo pozo; bajo deja al sistema oscilar/\"cazar\" entre los dos.", "", ""};
        t["CHAOS"]["freeze"] = LearnEntry{"Congela la dinámica en el valor actual.", "", ""};
