        t["CHAOS"]["out:out"] = LearnEntry{"La posición del sistema, siempre en [−1,1] — la señal caótica de pozo doble.", "Sin el \"empujón\" periódico (ligado a RATE), el sistema nunca cruza de un pozo al otro por sí solo — es una EDO determinista sin forzamiento.", "Suba DRIVE cerca del máximo con DAMP bajo: el sistema \"caza\" entre los dos pozos de forma imprevisible."};
        t["SH"]["rate"] = LearnEntry{"Reloj interno, usado sólo si TRIG1/2 está libre.", "", ""};
